    // 3. I18N
    I18n: {
        setLang: (l, reload = true) => { App.State.lang = l; localStorage.setItem('se_lang', l); if(App.State.user) App.API.updateLang(l); if(reload) { App.UI.showReload(); } else { document.documentElement.setAttribute('dir', l === 'ar' ? 'rtl' : 'ltr'); App.UI.updateIcons(); App.I18n.updateDOM(); App.Cart.render(); App.Catalog.renderBatch(true); App.Cart.renderZones(App.Config.zoneData); const bc = document.getElementById('breadcrumbs'); if(bc && (bc.innerHTML.includes("Home") || bc.innerHTML.includes("Accueil") || bc.innerHTML.includes("الرئيسية"))) { App.Router.go(App.State.currentView || 'home'); } } },
        t: (key) => { if(!key) return ""; let dict = App.State.translations[key]; if (!dict) { const foundKey = Object.keys(App.State.translations).find(k => k.toLowerCase() === key.toLowerCase()); if (foundKey) dict = App.State.translations[foundKey]; } if(dict) { const val = dict[App.State.lang]; if(val && (val.includes("#NAME?") || val.includes("#ERROR"))) return dict['en']; return val || dict['en']; } return key; },
        updateDOM: () => { 
            document.querySelectorAll('[data-i18n]').forEach(el => { const key = el.getAttribute('data-i18n'); if(key) el.innerText = App.I18n.t(key); }); 
            const phMap = {'login-phone': 'ph_phone', 'login-pass': 'ph_password', 'reg-name': 'ph_name', 'reg-phone': 'ph_phone', 'reg-pass': 'ph_password', 'addr-name': 'ph_name', 'addr-street': 'ph_address', 'addr-apt': 'ph_address', 'addr-city': 'lbl_city', 'addr-zip': 'lbl_zip', 'chk-name': 'ph_name', 'chk-phone': 'ph_phone', 'chk-address': 'ph_address', 'order-note': 'ph_notes', 'setting-name': 'ph_name', 'setting-email': 'lbl_email', 'res-name': 'ph_name', 'res-phone': 'ph_phone', 'review-comment': 'ph_review', 'admin-pw': 'ph_pin', 'coupon-code': 'lbl_extras', 'res-date': 'lbl_date', 'driver-pin': 'ph_driver_pin'}; 

            Object.keys(phMap).forEach(id => { const el = document.getElementById(id); if(el) el.placeholder = App.I18n.t(phMap[id]) || el.placeholder; }); 

            // Generic Placeholder Translator
            document.querySelectorAll('[data-i18n-ph]').forEach(el => {
                const key = el.getAttribute('data-i18n-ph');
                if(key) el.placeholder = App.I18n.t(key);
            });

            const search = document.getElementById('search-input'); if(search) search.placeholder = App.I18n.t('search_ph') || "Search..."; const typeSel = document.getElementById('addr-type'); if(typeSel) { if(typeSel.options[0]) typeSel.options[0].text = App.I18n.t('lbl_home'); if(typeSel.options[1]) typeSel.options[1].text = App.I18n.t('lbl_office'); } const countryInput = document.getElementById('addr-country'); if(countryInput) { const current = countryInput.value; if (!current || current.includes('Morocco') || current.includes('Maroc')) countryInput.value = App.I18n.t('val_morocco'); } },
        fetch: () => { fetch(API_URL + '?action=getTranslations').then(r=>r.json()).then(res=>{ if(res.status==='success') { App.State.translations = {...App.State.translations, ...res.data}; App.I18n.updateDOM(); App.Cart.render(); } }); }
    }, 

    // 4. UTILS
    Utils: {
        fmt: (price) => { 
            // SAFETY CHECK: Ensure price is a number
            let p = parseFloat(price);
            if (isNaN(p)) p = 0; 

            const c = App.State.currency; 
            const l = App.State.lang; 
            const val = (p * (App.State.exchange[c] || 1)).toFixed(2); 

            if (c === 'MAD') return l === 'ar' ? `${val} د.م.` : `${val} DH`; 
            if (c === 'EUR') return `€${val}`; 
            if (c === 'USD') return `$${val}`; 
            return `${val} ${c}`; 
        },
        save: (key, val) => localStorage.setItem(key, JSON.stringify(val)),
        load: (key) => { try { return JSON.parse(localStorage.getItem(key)) } catch(e) { return null } },
        el: (id) => document.getElementById(id) || { classList: { remove:()=>{}, add:()=>{} }, innerText: '', innerHTML: '', value: '' },
        checkStock: (i) => { if(i.stock === 0) return { disabled: true, badge: `<span class="badge-float badge-out">${App.I18n.t('lbl_sold_out')}</span>` }; if(i.stock < 5) return { disabled: false, badge: `<span class="badge-float badge-low">${App.I18n.t('lbl_low_stock')}</span>` }; if(String(i.tags).includes('on_sale')) return { disabled: false, badge: `<span class="badge-float bg-success">${App.I18n.t('lbl_on_sale')}</span>` }; if(String(i.tags).includes('hot')) return { disabled: false, badge: `<span class="badge-float badge-hot">${App.I18n.t('lbl_hot')}</span>` }; return { disabled: false, badge: '' }; },
        getLocalizedText: (obj) => { if(typeof obj === 'string') return obj; if(!obj) return ""; return obj[App.State.lang] || obj['en'] || ""; },
        isValidPhone: (p) => { var clean = String(p).replace(/[\s\-\(\)]/g, ''); return /^(?:(?:\+|00)212|0)[67]\d{8}$/.test(clean); },
        optimizeImg: (url) => { if(!url) return IMG_FALLBACK; if(url.includes('blogger.googleusercontent.com')) return url.replace(/\/s\d+\//, '/w400-h400-c/'); return url; },
        debounce: (func, wait) => { let timeout; return function(...args) { const context = this; clearTimeout(timeout); timeout = setTimeout(() => func.apply(context, args), wait); }; }
    }, 

    // 5. CATALOG
    Catalog: {
        searchDebounced: null,
        search: (q) => { if(App.Catalog.searchDebounced) App.Catalog.searchDebounced(q); },
        _searchImpl: (q) => { App.State.searchTerm = q.toLowerCase(); App.UI.transition(() => App.Catalog.renderBatch(true)); },
        renderFilters: () => { const c = document.getElementById('category-filters'); if(!c) return; const cats = ['All', ...new Set(App.State.catalog.map(i => i.category))]; c.innerHTML = cats.map(c => { const key = 'cat_' + c.toLowerCase().replace(/\s+/g, '_'); const trans = App.I18n.t(key); const label = (trans && trans !== key) ? trans : c; return `<div class="filter-chip ${c==='All'?'active':''}" onclick="App.Catalog.setCat('${c}', this)">${label}</div>` }).join(''); },
        setCat: (cat, el) => { App.State.activeCat = cat; document.querySelectorAll('.filter-chip').forEach(e => e.classList.remove('active')); el.classList.add('active'); App.UI.transition(() => App.Catalog.renderBatch(true)); },
        renderBatch: (reset=false) => { const grid = document.getElementById('product-grid-root'); if(!grid) return; if(reset) { grid.innerHTML = ''; App.State.visibleCount = 0; } let data = App.State.catalog.filter(i => { const catMatch = (App.State.activeCat === 'All' || i.category === App.State.activeCat); let searchMatch = true; if(App.State.searchTerm) { const txt = (Object.values(i.title).join(' ') + " " + i.tags).toLowerCase(); searchMatch = txt.includes(App.State.searchTerm); } return catMatch && searchMatch; }); const batch = data.slice(App.State.visibleCount, App.State.visibleCount + App.State.batchSize); if(batch.length === 0 && reset) grid.innerHTML = `<div class="col-12 text-center py-5 text-muted">${App.I18n.t('catalog_empty')}</div>`; batch.forEach(i => grid.innerHTML += App.UI.renderCard(i)); App.State.visibleCount += App.State.batchSize; }
    },

    // 6. UI
    UI: {
        toast: (msg, type='info') => { const c = document.getElementById('toast-container'); const t = document.createElement('div'); t.className = `custom-toast border-${type}`; t.innerHTML = `<span>${msg}</span><button type="button" class="btn-close btn-close-sm" onclick="this.parentElement.remove()"></button>`; c.appendChild(t); setTimeout(() => t.remove(), 3000); },
        confirm: (title, msg, callback) => { App.Utils.el('conf-title').innerText = title; App.Utils.el('conf-msg').innerText = msg; const btn = document.getElementById('conf-btn'); const modal = new bootstrap.Modal(document.getElementById('confirmModal')); const newBtn = btn.cloneNode(true); btn.parentNode.replaceChild(newBtn, btn); newBtn.innerText = App.I18n.t('btn_yes'); const cancelBtn = document.querySelector('#confirmModal button[data-i18n="btn_cancel"]'); if(cancelBtn) cancelBtn.innerText = App.I18n.t('btn_cancel'); newBtn.onclick = () => { callback(); modal.hide(); }; modal.show(); },
        openReviewModal: (pid) => { const p = App.State.catalog.find(x => String(x.id) === String(pid)); if(!p) return; App.State.tempReviewPid = pid; App.State.tempRating = 0; document.getElementById('review-comment').value = ''; document.getElementById('review-prod-name').innerText = App.Utils.getLocalizedText(p.title); App.UI.setStar(0); new bootstrap.Modal(document.getElementById('reviewModal')).show(); },
        setStar: (n) => { App.State.tempRating = n; for(let i=1; i<=5; i++) { const s = document.getElementById('star-'+i); if(i <= n) { s.classList.remove('bi-star', 'text-muted'); s.classList.add('bi-star-fill', 'text-warning'); } else { s.classList.remove('bi-star-fill', 'text-warning'); s.classList.add('bi-star', 'text-muted'); } } },
        setCurrency: (newCurr) => { App.State.lastCurrencyChange = Date.now(); App.State.currency = newCurr; localStorage.setItem('se_curr', newCurr); if(App.State.user) App.API.push('pref'); App.UI.showReload(); },
        selectWelcomeOption: (type, val) => { if(type === 'lang') { App.State.tempLang = val; ['en','fr','ar'].forEach(l => document.getElementById('wel-lang-'+l).classList.remove('selected')); document.getElementById('wel-lang-'+val).classList.add('selected'); const btn = document.getElementById('btn-welcome-start'); if(btn && App.State.translations['btn_start_ordering']) { btn.innerText = App.State.translations['btn_start_ordering'][val]; } } else { App.State.tempCurr = val; ['MAD','EUR','USD'].forEach(c => document.getElementById('wel-curr-'+c).classList.remove('selected')); document.getElementById('wel-curr-'+val).classList.add('selected'); } },
        finishWelcome: () => { const l = App.State.tempLang; const c = App.State.tempCurr; localStorage.setItem('se_setup_done', 'true'); localStorage.setItem('se_lang', l); localStorage.setItem('se_curr', c); location.reload(); },
        updateIcons: () => { const l = App.State.lang; const flagBtn = document.getElementById('header-lang-icon'); if(flagBtn && App.State.flags[l]) flagBtn.src = App.State.flags[l]; const setLangBtn = document.getElementById('setting-lang-icon'); if(setLangBtn && App.State.flags[l]) setLangBtn.src = App.State.flags[l]; const c = App.State.currency; const setCurrDisplay = document.getElementById('setting-curr-display'); if(setCurrDisplay) { if (c === 'MAD') setCurrDisplay.innerText = (l === 'ar') ? "د.م." : "MAD"; else if (c === 'EUR') setCurrDisplay.innerText = "EUR"; else setCurrDisplay.innerText = "USD"; } },
        toggleTheme: () => { const body = document.body; const isDark = body.getAttribute('data-theme') === 'dark'; body.setAttribute('data-theme', isDark ? 'light' : 'dark'); if(document.getElementById('theme-toggle')) document.getElementById('theme-toggle').checked = !isDark; localStorage.setItem('se_theme', !isDark ? 'dark' : 'light'); },
        hideLoader: () => { const l = document.getElementById('global-loader'); if(l) { l.style.opacity = '0'; setTimeout(() => l.remove(), 500); } },
        showReload: () => { let l = document.getElementById('global-loader'); if(!l) { l = document.createElement('div'); l.id = 'global-loader'; l.style.cssText = "position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: var(--bg-body); z-index: 9999; display: flex; flex-direction: column; justify-content: center; align-items: center; opacity: 1;"; document.body.appendChild(l); } l.innerHTML = `<div class='spinner-border text-primary' role='status' style='width:3rem; height:3rem; border-width:4px;'></div><div class='mt-2 fw-bold text-muted'>${App.I18n.t('msg_updating')}</div>`; l.style.display = 'flex'; l.style.opacity = '1'; setTimeout(() => location.reload(), 500); },
        flyToCart: (imgEl) => { if(!imgEl) return; const cartBtn = document.getElementById('nav-cart-btn'); if(!cartBtn) return; const fly = imgEl.cloneNode(); const rect = imgEl.getBoundingClientRect(); fly.classList.add('flying-img'); fly.style.left = rect.left + 'px'; fly.style.top = rect.top + 'px'; fly.style.width = rect.width + 'px'; fly.style.height = rect.height + 'px'; document.body.appendChild(fly); const cartRect = cartBtn.getBoundingClientRect(); setTimeout(() => { fly.style.left = (cartRect.left + 10) + 'px'; fly.style.top = (cartRect.top + 10) + 'px'; fly.style.width = '20px'; fly.style.height = '20px'; fly.style.opacity = '0'; }, 50); setTimeout(() => fly.remove(), 850); },
        updateHearts: (id, isActive) => { document.querySelectorAll(`.wish-btn-card[data-id="${id}"]`).forEach(b => { if(isActive) { b.classList.add('active'); b.innerHTML = '<i class="bi bi-heart-fill text-danger"></i>'; } else { b.classList.remove('active'); b.innerHTML = '<i class="bi bi-heart"></i>'; } }); },
        transition: (cb) => { const grid = document.getElementById('product-grid-root'); if(grid) grid.innerHTML = Array(4).fill('<div class="col-6 col-md-3"><div class="skeleton" style="height:250px"></div></div>').join(''); setTimeout(() => { if(cb) cb(); }, 300); },
        showCartNotification: () => { const n = document.getElementById('cart-notification'); const c = document.getElementById('cn-count'); if(n && c) { c.innerText = App.State.cart.reduce((a,b)=>a+b.qty, 0); n.classList.add('active'); if(App.State.notifyTimeout) clearTimeout(App.State.notifyTimeout); App.State.notifyTimeout = setTimeout(() => { n.classList.remove('active'); }, 5000); } },
        renderCard: (i, isGrid=true) => { const stock = App.Utils.checkStock(i); const isWish = App.State.wishlist.includes(String(i.id)); const heartClass = isWish ? 'active' : ''; const heartIcon = isWish ? 'bi-heart-fill text-danger' : 'bi-heart'; const colClass = isGrid ? 'col-6 col-md-4 col-lg-3' : 'col-6 col-md-3'; const displayTitle = App.Utils.getLocalizedText(i.title); const safeId = String(i.id).replace(/'/g, "\\'"); let priceHtml = `<span class="text-primary fw-bold">${App.Utils.fmt(i.price_MAD)}</span>`; if(i.old_price_MAD > i.price_MAD) priceHtml = `<div class="d-flex align-items-center gap-2"><s class="text-muted small">${App.Utils.fmt(i.old_price_MAD)}</s> <span class="text-danger fw-bold">${App.Utils.fmt(i.price_MAD)}</span></div>`; 
        const optImg = App.Utils.optimizeImg(i.image || IMG_FALLBACK); 
        return `<div class="${colClass}"><div class="product-card h-100">${stock.badge}<div class="product-img-wrapper" onclick="App.QuickView.open('${safeId}')"><img src="${optImg}" class="product-img img-fade" onload="this.style.opacity=1" loading="lazy" /><button class="wish-btn-card ${heartClass}" data-id="${safeId}" onclick="event.stopPropagation(); event.preventDefault(); App.Wishlist.toggle('${safeId}'); return false;" type="button"><i class="bi ${heartIcon}"></i></button></div><div class="p-3"><div class="star-rating"><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-half"></i> <span class="text-muted small">(4.5)</span></div><h6 class="product-title">${displayTitle}</h6><div class="d-flex justify-content-between align-items-center">${priceHtml}<button class="btn btn-sm btn-dark rounded-circle" ${stock.disabled ? 'disabled="disabled"' : ''} onclick="event.stopPropagation(); event.preventDefault(); App.Cart.add('${safeId}', this); return false;" type="button"><i class="bi bi-plus"></i></button></div></div></div></div>`; },
        renderQuickView: (p) => { 
            const stock = App.Utils.checkStock(p); const displayTitle = App.Utils.getLocalizedText(p.title);
            let rawDesc = App.Utils.getLocalizedText(p.desc); const cleanDesc = rawDesc.replace(/<[^>]*>?/gm, ''); 
            const safeId = String(p.id).replace(/'/g, "\\'");
            let priceHtml = `<div class="h3 text-primary fw-bold m-0" id="qv-price-display">${App.Utils.fmt(p.price_MAD)}</div>`;
            if(p.old_price_MAD > p.price_MAD) priceHtml = `<div class="d-flex align-items-baseline gap-2"><s class="text-muted h5 m-0" id="qv-old-price-display">${App.Utils.fmt(p.old_price_MAD)}</s> <div class="h3 text-danger fw-bold m-0" id="qv-price-display">${App.Utils.fmt(p.price_MAD)}</div></div>`;
            let relatedHtml = ''; const related = App.State.catalog.filter(x => x.category === p.category && x.id !== p.id).slice(0, 2); 
            if(related.length > 0) { relatedHtml = `<div class="mt-4 border-top pt-3"><h6 class="fw-bold mb-3 small text-muted" data-i18n="lbl_related">${App.I18n.t('lbl_related')}</h6><div class="d-flex gap-2">${related.map(r => `<div class="related-item flex-fill" onclick="App.QuickView.open('${String(r.id).replace(/'/g, "\\'")}')"><img src="${App.Utils.optimizeImg(r.image || IMG_FALLBACK)}" class="related-img"/><div style="min-width:0"><div class="small fw-bold text-truncate">${App.Utils.getLocalizedText(r.title)}</div><div class="small text-primary fw-bold">${App.Utils.fmt(r.price_MAD)}</div></div></div>`).join('')}</div></div>`; } 
            let extrasHtml = ''; if(p.extras && p.extras.length > 0) { const extrasContent = p.extras.map(e => { const eName = App.Utils.getLocalizedText(e.name); const eVal = typeof e.name === 'string' ? e.name : e.name.en; return `<div class="extra-item"><div class="form-check m-0"><input class="form-check-input extra-check" type="checkbox" value="${eVal}" id="ex-${eVal.replace(/\s+/g,'')}" data-price="${e.price}"><label class="form-check-label small" for="ex-${eVal.replace(/\s+/g,'')}">${eName}</label></div><span class="text-primary fw-bold small">+${App.Utils.fmt(e.price)}</span></div>`; }).join(''); extrasHtml = `<div class="mb-4 bg-light p-3 rounded"><h6 class="small fw-bold text-muted mb-2" data-i18n="lbl_extras">${App.I18n.t('lbl_extras')}</h6>${extrasContent}</div>`; }
            let reviewsHtml = `<div class="mt-4 border-top pt-3"><h6 class="fw-bold mb-3" data-i18n="lbl_reviews">${App.I18n.t('lbl_reviews')}</h6><div id="qv-reviews-list"><div class="spinner-border spinner-border-sm text-primary"></div></div></div>`;
            return `<div class="row g-0" id="qv-content-wrapper"><div class="col-md-5 qv-img-container"><img src="${p.image || IMG_FALLBACK}" class="qv-img img-fade" onload="this.style.opacity=1" style="pointer-events:none; user-select:none;"/></div><div class="col-md-7 p-4 d-flex flex-column"><div class="d-flex justify-content-between align-items-start"><div><h4 class="fw-bold mb-1">${displayTitle}</h4><span class="badge bg-secondary">${App.I18n.t('cat_' + p.category.toLowerCase().replace(/\s+/g, '_'))}</span></div><button class="btn-close" data-bs-dismiss="modal" type="button"></button></div><div class="text-muted small mb-3">${cleanDesc || App.I18n.t('txt_prem_ing')}</div><div class="mb-4"><label class="small fw-bold text-muted mb-2" style="font-size:0.7rem">${App.I18n.t('lbl_size_var')}</label><div class="btn-group w-100 btn-pill-group" role="group"><input type="radio" class="btn-check" name="qv-size" id="size-reg" value="1" checked="checked" onchange="App.QuickView.updatePrice(${p.price_MAD}, ${p.old_price_MAD})"><label class="btn btn-outline-secondary" for="size-reg">${App.I18n.t('opt_regular')}</label><input type="radio" class="btn-check" name="qv-size" id="size-box" value="1.2" onchange="App.QuickView.updatePrice(${p.price_MAD}, ${p.old_price_MAD})"><label class="btn btn-outline-secondary" for="size-box">${App.I18n.t('opt_box')}</label><input type="radio" class="btn-check" name="qv-size" id="size-party" value="1.5" onchange="App.QuickView.updatePrice(${p.price_MAD}, ${p.old_price_MAD})"><label class="btn btn-outline-secondary" for="size-party">${App.I18n.t('opt_party')}</label></div></div>${extrasHtml}<div class="d-flex justify-content-between align-items-center pt-3 border-top mt-auto">${priceHtml}<div class="d-flex gap-2 align-items-center"><div class="input-group input-group-sm" style="width:100px"><button class="btn btn-outline-secondary" type="button" onclick="event.preventDefault(); event.stopPropagation(); App.QuickView.updateQty(-1); return false;">-</button><input type="number" value="1" min="1" id="qv-qty" class="form-control text-center border-0" readonly><button class="btn btn-outline-secondary" type="button" onclick="event.preventDefault(); event.stopPropagation(); App.QuickView.updateQty(1); return false;">+</button></div><button class="btn btn-dark btn-sm rounded-pill fw-bold px-4 py-2" ${stock.disabled ? 'disabled' : ''} type="button" onclick="event.preventDefault(); event.stopPropagation(); App.QuickView.addToCart('${safeId}'); return false;">${App.I18n.t('btn_add_caps')}</button></div></div>${relatedHtml}${reviewsHtml}</div></div></div>`; 
        },
        updatePrice: (base, oldBase) => { const mult = parseFloat(document.querySelector('input[name="qv-size"]:checked').value); document.getElementById('qv-price-display').innerText = App.Utils.fmt(base * mult); const oldEl = document.getElementById('qv-old-price-display'); if(oldEl && oldBase) oldEl.innerText = App.Utils.fmt(oldBase * mult); },
        updateQty: (delta) => { const el = document.getElementById('qv-qty'); if(!el) return; let val = parseInt(el.value) || 1; val += delta; if(val < 1) val = 1; el.value = val; },
        addToCart: (id) => { const qtyInput = document.getElementById('qv-qty'); let sizeInput = document.querySelector('input[name="qv-size"]:checked'); if(!sizeInput) sizeInput = document.getElementById('size-reg'); const qty = qtyInput ? parseInt(qtyInput.value) : 1; const el = sizeInput || { value: 1, id: 'size-reg' }; let labelText = "Regular"; if(sizeInput) { const label = document.querySelector(`label[for="${sizeInput.id}"]`); if(label) labelText = label.innerText; } const extras = []; document.querySelectorAll('.extra-check:checked').forEach(c => extras.push(c.value)); const variant = { mult: parseFloat(el.value), name: labelText }; App.Cart.add(id, null, qty, variant, extras); bootstrap.Modal.getInstance(document.getElementById('quickViewModal')).hide(); }
    },

    // 7. CART & CHECKOUT (Phase 7 Updated)
    Cart: {
        add: (id, btn, qty=1, variant={mult:1, name:'Regular'}, extras=[]) => { const p = App.State.catalog.find(x => String(x.id) === String(id)); if(!p) return; if(btn) { btn.classList.add('btn-clicked'); setTimeout(() => btn.classList.remove('btn-clicked'), 150); App.UI.flyToCart(btn.closest('.product-card').querySelector('.product-img')); } let existing = App.State.cart.find(x => x.id === id && x.variant.name === variant.name && JSON.stringify(x.extras.sort()) === JSON.stringify(extras.sort())); if(existing) { existing.qty += qty; } else { App.State.cart.push({ id: id, qty: qty, title: p.title, price: p.price_MAD, image: p.image, variant: variant, extras: extras }); } App.Utils.save('se_cart', App.State.cart); App.UI.showCartNotification(); App.UI.toast(App.I18n.t('cart_updated'), 'success'); if(App.State.currentView === 'cart') App.Cart.render(); if(App.State.user) App.API.push('cart'); },
        remove: (idx) => { App.UI.confirm(App.I18n.t('cart_remove_title'), App.I18n.t('cart_remove_msg'), () => { App.State.cart.splice(idx, 1); App.Utils.save('se_cart', App.State.cart); App.Cart.render(); App.UI.showCartNotification(); if(App.State.user) App.API.push('cart'); }); },
        update: (idx, delta) => { if(App.State.cart[idx].qty + delta < 1) return; App.State.cart[idx].qty += delta; App.Utils.save('se_cart', App.State.cart); App.Cart.render(); App.UI.showCartNotification(); if(App.State.user) App.API.push('cart'); },
        empty: () => { if(App.State.cart.length === 0) return; App.UI.confirm(App.I18n.t('cart_empty_title'), App.I18n.t('cart_empty_msg'), () => { App.State.cart = []; App.Utils.save('se_cart', []); App.Cart.render(); App.UI.showCartNotification(); if(App.State.user) App.API.push('cart'); }); },
        render: () => {
            const el = document.getElementById('cart-list'); const empty = document.getElementById('cart-empty-state'); const content = document.getElementById('cart-content'); const badge = document.getElementById('nav-cart-count'); if(badge) badge.innerText = App.State.cart.reduce((a,b)=>a+b.qty,0);
            if(App.State.cart.length === 0) { if(empty) empty.classList.remove('d-none'); if(content) content.classList.add('d-none'); } else {
                if(empty) empty.classList.add('d-none'); if(content) content.classList.remove('d-none'); if(el) {
                    el.innerHTML = App.State.cart.map((i, idx) => {
                        const basePrice = i.price * i.variant.mult; let extraCost = 0; if(i.extras) { i.extras.forEach(eName => { const pObj = App.State.catalog.find(x => String(x.id) === String(i.id)); if(pObj && pObj.extras) { const found = pObj.extras.find(ex => (typeof ex.name === 'string' ? ex.name : ex.name.en) === eName); if(found) extraCost += Number(found.price); } }); } const finalUnit = basePrice + extraCost; const total = finalUnit * i.qty;
                        const extrasDisplay = i.extras && i.extras.length > 0 ? `<div class="small text-muted">+ ${i.extras.join(', ')}</div>` : '';
                        return `<div class="cart-item-card"><img src="${App.Utils.optimizeImg(i.image || IMG_FALLBACK)}" class="cart-item-img"/> <div class="flex-grow-1"> <div class="d-flex justify-content-between align-items-start"> <div> <h6 class="fw-bold mb-1">${App.Utils.getLocalizedText(i.title)}</h6> <div class="small text-muted">${i.variant.name !== 'Regular' ? i.variant.name : ''}</div> ${extrasDisplay} <div class="text-primary fw-bold mt-1">${App.Utils.fmt(finalUnit)}</div> </div> <i class="bi bi-trash text-danger action-icon" onclick="App.Cart.remove(${idx})"></i> </div> <div class="d-flex justify-content-between align-items-end mt-2"> <div class="qty-selector"> <button class="qty-btn" onclick="App.Cart.update(${idx}, -1)">-</button> <span class="px-2 small fw-bold">${i.qty}</span> <button class="qty-btn" onclick="App.Cart.update(${idx}, 1)">+</button> </div> <span class="fw-bold">${App.Utils.fmt(total)}</span> </div> </div> </div>`;
                    }).join('');
                } App.Cart.calculateTotal();
            }
        },
        calculateTotal: () => {
            let sub = 0; App.State.cart.forEach(i => { const base = i.price * i.variant.mult; let extra = 0; if(i.extras) { i.extras.forEach(eName => { const pObj = App.State.catalog.find(x => String(x.id) === String(i.id)); if(pObj && pObj.extras) { const found = pObj.extras.find(ex => (typeof ex.name === 'string' ? ex.name : ex.name.en) === eName); if(found) extra += Number(found.price); } }); } sub += (base + extra) * i.qty; });
            const zone = document.getElementById('chk-zone').value; const shipCost = (zone && App.Config.deliveryZones['Delivery_' + zone]) ? App.Config.deliveryZones['Delivery_' + zone] : 0;
            const freeShip = sub >= App.Config.freeShipThreshold; const finalShip = freeShip ? 0 : shipCost;

            // Progress Bar Logic
            const barFill = document.getElementById('delivery-bar-fill');
            const msgEl = document.getElementById('delivery-msg');
            const amtEl = document.getElementById('delivery-amt');

            if(barFill && msgEl && amtEl) {
                const pct = Math.min((sub / App.Config.freeShipThreshold) * 100, 100);
                barFill.style.width = pct + '%';
                if(pct >= 100) {
                    barFill.style.background = '#198754';
                    msgEl.innerText = App.I18n.t('lbl_delivery_free');
                    msgEl.className = 'text-success fw-bold';
                    amtEl.innerText = "";
                } else {
                    barFill.style.background = '#ffc107';
                    const remain = App.Config.freeShipThreshold - sub;
                    msgEl.innerText = App.I18n.t('lbl_delivery_more');
                    msgEl.className = 'text-muted';
                    amtEl.innerText = App.Utils.fmt(remain);
                }
            }

            let discount = 0; if(App.State.activeCoupon) discount = sub * App.State.activeCoupon.discount;

            // Points Logic
            let pointsDiscount = 0;
            const usePoints = document.getElementById('use-points-switch');
            const rowPoints = document.getElementById('row-points');
            const pointsVal = document.getElementById('cart-points-disc');

            if (usePoints && usePoints.checked && App.State.user) {
                const maxDiscount = sub * 0.50; // Max 50% off
                const userPointsVal = App.State.user.points / 10;
                pointsDiscount = Math.min(maxDiscount, userPointsVal);
                if(rowPoints) rowPoints.classList.remove('d-none');
                if(pointsVal) pointsVal.innerText = "-" + App.Utils.fmt(pointsDiscount);
            } else {
                if(rowPoints) rowPoints.classList.add('d-none');
            }

            const total = sub + finalShip - discount - pointsDiscount;

            if(document.getElementById('cart-subtotal')) document.getElementById('cart-subtotal').innerText = App.Utils.fmt(sub);
            if(document.getElementById('cart-delivery')) document.getElementById('cart-delivery').innerText = freeShip ? App.I18n.t('lbl_free') : App.Utils.fmt(finalShip);
            if(document.getElementById('cart-total')) document.getElementById('cart-total').innerText = App.Utils.fmt(total);
            if(discount > 0) { document.getElementById('row-disc').classList.remove('d-none'); document.getElementById('cart-disc').innerText = '-' + App.Utils.fmt(discount); } else { document.getElementById('row-disc').classList.add('d-none'); }
        },
        applyCoupon: () => { const code = document.getElementById('coupon-code').value.trim(); if(!code) return; const fb = document.getElementById('coupon-feedback'); fb.innerText = App.I18n.t('msg_verifying'); fb.className = 'small text-end mb-2 text-warning'; fetch(API_URL + '?action=checkCoupon', {method:'POST', body:JSON.stringify({action:'checkCoupon', data:{code:code}})}).then(r=>r.json()).then(res=>{ if(res.status==='success') { App.State.activeCoupon = res; fb.innerText = `${res.code} ${App.I18n.t('msg_active')} (${res.discount*100}% ${App.I18n.t('msg_off')})`; fb.className = 'small text-end mb-2 text-success fw-bold'; App.Cart.calculateTotal(); } else { App.State.activeCoupon = null; fb.innerText = App.I18n.t('msg_code_invalid'); fb.className = 'small text-end mb-2 text-danger'; App.Cart.calculateTotal(); } }); },

        renderZones: (config) => { 
            const s = document.getElementById('chk-zone'); 
            if(!s) return; 
            s.innerHTML = `<option value="">${App.I18n.t('select_zone_ph')}</option>`; 
            Object.keys(config).forEach(k => { 
                if(k.startsWith('Delivery_')) { 
                    const zoneName = k.replace('Delivery_', ''); 
                    // Try to translate "zone_maarif", else use "Maarif"
                    const tKey = 'zone_' + zoneName.toLowerCase();
                    const label = (App.State.translations[tKey]) ? App.I18n.t(tKey) : zoneName;
                    s.innerHTML += `<option value="${zoneName}">${label} (${config[k]} DH)</option>`; 
                } 
            }); 
        },

        fillAddress: () => { const sel = document.getElementById('cart-addr-select'); if(!sel || !sel.value) return; const type = sel.value.toLowerCase(); const data = App.State.addresses[type]; if(data) { document.getElementById('chk-address').value = (typeof data === 'string') ? data : data.full; document.getElementById('chk-zone').focus(); } },
        togglePoints: () => { App.Cart.calculateTotal(); },
        reorder: (itemsJsonStr) => {
            // "Order Again" Logic - Phase 7
            try {
                let items = [];
                // Handle different storage formats (string vs json)
                if (itemsJsonStr.startsWith('[')) {
                    items = JSON.parse(itemsJsonStr);
                } else {
                    items = [itemsJsonStr]; 
                }

                let addedCount = 0;

                items.forEach(itemStr => {
                    // Expected format: "2x Salmon Sushi (Extra Wasabi)" or "1x Cola"
                    const regex = /^(\d+)x\s(.+)$/;
                    const match = itemStr.match(regex);

                    if (match) {
                        const qty = parseInt(match[1]);
                        let rest = match[2];
                        let extras = [];

                        // Extract extras if present in parenthesis
                        if (rest.includes('(') && rest.includes(')')) {
                            const parts = rest.split('(');
                            rest = parts[0].trim();
                            const extrasStr = parts[1].replace(')', '');
                            extras = extrasStr.split(',').map(s => s.trim());
                        }

                        // Fuzzy find product by title
                        let foundProd = null;
                        for(let i=0; i<App.State.catalog.length; i++) {
                            const p = App.State.catalog[i];
                            // Check all languages
                            if ( (typeof p.title === 'object' && (p.title.en === rest || p.title.fr === rest || p.title.ar === rest)) || 
                                 (typeof p.title === 'string' && p.title === rest) ) {
                                foundProd = p;
                                break;
                            }
                        }

                        if (foundProd) {
                            // Check variant based on price multipliers (simplified: assume regular for reorder)
                            const variant = {mult: 1, name: 'Regular'};
                            App.Cart.add(foundProd.id, null, qty, variant, extras);
                            addedCount++;
                        }
                    }
                });

                if (addedCount > 0) {
                    App.Router.go('cart');
                    App.UI.toast(`${addedCount} items added to cart`, 'success');
                } else {
                    App.UI.toast("Could not find items", 'error');
                }

            } catch (e) {
                console.error("Reorder failed", e);
                App.UI.toast("Error reordering", 'error');
            }
        }
    },

    // 8. API
    API: {
        init: () => {
            fetch(API_URL + '?action=checkStoreStatus').then(r=>r.json()).then(res => {
                if(res.status === 'success') {
                   App.Config = {...App.Config, ...res.config, deliveryZones: res.config};
                   App.Cart.renderZones(res.config);
                   if(!res.isOpen) document.body.classList.add('is-closed');
                }
            });
            fetch(API_URL + '?action=getCatalog').then(r=>r.json()).then(res => {
                if(res.status === 'success') {
                    App.State.catalog = res.data;
                    App.Catalog.renderFilters();
                    App.Catalog.renderBatch(true);
                    if(App.State.user) App.API.fetchUserData();
                }
            });
            App.I18n.fetch();
        },
        fetchUserData: () => {
            const u = App.State.user;
            if (!u) return;
            fetch(API_URL + '?action=getUserData&userId=' + u.id + '&token=' + u.authToken).then(r=>r.json()).then(res => {
                if(res.status === 'success') {
                   if(res.wishlist) App.State.wishlist = res.wishlist.split(',');
                   if(res.cart && App.State.cart.length === 0) App.State.cart = JSON.parse(res.cart);
                   if(res.currency) App.State.currency = res.currency;
                   if(res.orders) App.State.history = res.orders;
                   if(res.addresses) App.State.addresses = res.addresses;
                   if(res.profile && res.profile.points) App.State.user.points = res.profile.points;

                   App.State.exchange['MAD'] = 1;
                   App.Utils.save('se_user', App.State.user);
                   App.Cart.render();
                   App.Auth.check();
                }
            });
        },
        push: (type) => {
            const u = App.State.user; if(!u) return;
            let action = '', data = { userId: u.id, authToken: u.authToken };
            if(type === 'cart') { action = 'syncCart'; data.cartJson = JSON.stringify(App.State.cart); data.currency = App.State.currency; }
            if(type === 'wish') { action = 'syncWishlist'; data.items = App.State.wishlist.join(','); }
            if(type === 'pref') { action = 'updatePreference'; data.currency = App.State.currency; }
            if(action) fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: action, data: data }) });
        },
        checkout: () => {
            const n = document.getElementById('chk-name').value;
            const p = document.getElementById('chk-phone').value;
            const a = document.getElementById('chk-address').value;
            const z = document.getElementById('chk-zone').value;
            const m = document.getElementById('chk-payment').value;
            const note = document.getElementById('order-note').value;
            const usePoints = document.getElementById('use-points-switch').checked;

            if(App.State.cart.length === 0) return alert(App.I18n.t('cart_empty'));
            if(!n || !p || !a || !z) return alert(App.I18n.t('msg_fill_fields'));
            if(!App.Utils.isValidPhone(p)) return alert(App.I18n.t('msg_invalid_phone'));

            const btn = document.getElementById('checkout-btn');
            btn.disabled = true;
            btn.innerText = "Processing...";

            const payload = { 
                name: n, phone: p, address: a, zone: z, 
                method: m, notes: note, cart: JSON.stringify(App.State.cart), 
                userId: App.State.user ? App.State.user.id : 'Guest', 
                authToken: App.State.user ? App.State.user.authToken : null,
                couponCode: App.State.activeCoupon ? App.State.activeCoupon.code : null,
                usePoints: usePoints
            };

            fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: 'placeOrder', data: payload }) })
            .then(r=>r.json()).then(res => {
                btn.disabled = false;
                btn.innerText = App.I18n.t('btn_checkout');
                if(res.status === 'success') {
                    // PHASE 7: Confetti Celebration
                    if(window.confetti) {
                        confetti({ particleCount: 150, spread: 70, origin: { y: 0.6 } });
                    }

                    if(m === 'cod' || m === 'cp') {
                        // WhatsApp Integration
                        const total = res.secureTotal || "0.00";
                        const itemsList = App.State.cart.map(i => `${i.qty}x ${i.title}`).join('%0A');
                        let waMsg = `*New Order #${res.orderId}* %0A *Name:* ${n} %0A *Phone:* ${p} %0A *Address:* ${a} (${z}) %0A *Items:* %0A ${itemsList} %0A *Total:* ${total} DH`;

                        // Clear Cart
                        App.State.cart = []; App.Utils.save('se_cart', []); App.Cart.render(); App.UI.showCartNotification();

                        // Show Success Modal/Toast
                        App.UI.confirm(App.I18n.t('lbl_thank_you'), `Order #${res.orderId} placed! Open WhatsApp to confirm?`, () => {
                            window.open(`https://wa.me/${App.Config.waNumber}?text=${waMsg}`, '_blank');
                            App.Router.go('home');
                        });

                        // Update User Points locally if applicable
                        if(App.State.user && res.pointsRedeemed) {
                            App.State.user.points -= res.pointsRedeemed;
                            App.Profile.updatePointsUI();
                        }
                    }
                } else {
                    alert("Error: " + res.message);
                }
            }).catch(e => {
                btn.disabled = false;
                alert("Connection Error. Please try again.");
            });
        },
        bookTable: () => {
             const d = {
                name: document.getElementById('res-name').value,
                phone: document.getElementById('res-phone').value,
                date: document.getElementById('res-date').value,
                time: document.getElementById('res-time').value,
                guests: document.getElementById('res-guests').value,
                userId: App.State.user ? App.State.user.id : 'Guest'
            };
            if(!d.name || !d.phone || !d.date || !d.time) return alert(App.I18n.t('msg_fill_fields'));

            const btn = document.getElementById('btn-book-table');
            btn.disabled = true; btn.innerText = "Booking...";

            fetch(API_URL, {method:'POST', body:JSON.stringify({action:'bookTable', data:d})}).then(r=>r.json()).then(res=>{
                btn.disabled = false; btn.innerText = App.I18n.t('btn_book_now');
                if(res.status==='success') {
                    alert("Reservation Sent! We will confirm shortly.");
                    App.Router.go('home');
                } else alert(res.message);
            });
        },
        submitReview: () => {
            if(!App.State.user) return alert("Login to review");
            if(App.State.tempRating === 0) return alert("Select a star rating");
            const txt = document.getElementById('review-comment').value;
            fetch(API_URL, {method:'POST', body:JSON.stringify({action:'submitReview', data:{
                userId: App.State.user.id,
                userName: App.State.user.name,
                productId: App.State.tempReviewPid,
                rating: App.State.tempRating,
                comment: txt
            }})}).then(r=>r.json()).then(res=>{
                if(res.status==='success') {
                    App.UI.toast("Review Submitted!");
                    bootstrap.Modal.getInstance(document.getElementById('reviewModal')).hide();
                }
            });
        },

        updateLang: (l) => {
            const u = App.State.user;
            if(!u) return;
            fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: 'updateUser', data: { userId: u.id, authToken: u.authToken, lang: l } }) });
        }
    },

    // 9. QUICK VIEW (Handled in UI)
    QuickView: {
        open: (id) => {
            const p = App.State.catalog.find(x => String(x.id) === String(id));
            if(!p) return;

            // Check cache for reviews
            if(!p.reviewsLoaded) {
                 fetch(API_URL + '?action=getReviews&productId=' + id).then(r=>r.json()).then(res=>{
                     if(res.status==='success') {
                         p.reviews = res.data;
                         p.reviewsLoaded = true;
                         // If modal is open, update it
                         const list = document.getElementById('qv-reviews-list');
                         if(list && document.getElementById('qv-body').innerHTML.includes(App.Utils.getLocalizedText(p.title))) {
                             App.QuickView.renderReviews(p.reviews, list);
                         }
                     }
                 });
            }

            document.getElementById('qv-body').innerHTML = App.UI.renderQuickView(p);
            new bootstrap.Modal(document.getElementById('quickViewModal')).show();

            // Render basic view immediately
            const list = document.getElementById('qv-reviews-list');
            if(p.reviewsLoaded) App.QuickView.renderReviews(p.reviews, list);
        },
        renderReviews: (reviews, container) => {
            if(reviews.length === 0) { container.innerHTML = '<p class="text-muted small">No reviews yet.</p>'; return; }
            container.innerHTML = reviews.map(r => `
                <div class="review-card">
                    <div class="d-flex justify-content-between mb-1">
                        <span class="fw-bold small">${r.user}</span>
                        <span class="text-warning small"><i class="bi bi-star-fill"></i> ${r.rating}</span>
                    </div>
                    <p class="small text-muted m-0">${r.comment}</p>
                </div>
            `).join('');
        },
        updatePrice: (base, oldBase) => { const mult = parseFloat(document.querySelector('input[name="qv-size"]:checked').value); document.getElementById('qv-price-display').innerText = App.Utils.fmt(base * mult); const oldEl = document.getElementById('qv-old-price-display'); if(oldEl && oldBase) oldEl.innerText = App.Utils.fmt(oldBase * mult); },
        updateQty: (delta) => { const el = document.getElementById('qv-qty'); if(!el) return; let val = parseInt(el.value) || 1; val += delta; if(val < 1) val = 1; el.value = val; },
        addToCart: (id) => { const qtyInput = document.getElementById('qv-qty'); let sizeInput = document.querySelector('input[name="qv-size"]:checked'); if(!sizeInput) sizeInput = document.getElementById('size-reg'); const qty = qtyInput ? parseInt(qtyInput.value) : 1; const el = sizeInput || { value: 1, id: 'size-reg' }; let labelText = "Regular"; if(sizeInput) { const label = document.querySelector(`label[for="${sizeInput.id}"]`); if(label) labelText = label.innerText; } const extras = []; document.querySelectorAll('.extra-check:checked').forEach(c => extras.push(c.value)); const variant = { mult: parseFloat(el.value), name: labelText }; App.Cart.add(id, null, qty, variant, extras); bootstrap.Modal.getInstance(document.getElementById('quickViewModal')).hide(); }
    },

    // 10. WISHLIST
    Wishlist: {
        toggle: (id) => { 
            if(!App.State.user) return App.Auth.openModal();
            const idx = App.State.wishlist.indexOf(String(id));
            if(idx > -1) { App.State.wishlist.splice(idx, 1); App.UI.toast(App.I18n.t('msg_wish_removed')); App.UI.updateHearts(id, false); } 
            else { App.State.wishlist.push(String(id)); App.UI.toast(App.I18n.t('msg_wish_added'), 'success'); App.UI.updateHearts(id, true); }
            App.Utils.save('se_wish', App.State.wishlist);
            document.getElementById('nav-wish-count').innerText = App.State.wishlist.length;
            App.API.push('wish');
            if(App.State.currentView === 'wishlist') App.Wishlist.render();
        },
        render: () => {
            const c = document.getElementById('profile-wishlist-grid');
            if(!c) return;
            if(App.State.wishlist.length === 0) { c.innerHTML = `<div class="col-12 text-center text-muted py-5">${App.I18n.t('wishlist_empty')}</div>`; return; }
            c.innerHTML = App.State.wishlist.map(id => {
                const p = App.State.catalog.find(x => String(x.id) === String(id));
                return p ? App.UI.renderCard(p) : '';
            }).join('');
        }
    },

    // 11. ADMIN
    Admin: {
        openLogin: () => new bootstrap.Modal(document.getElementById('adminLoginModal')).show(),
        login: () => { const p = document.getElementById('admin-pw').value; if(!p) return; App.State.adminPw = p; App.Admin.fetchDashboard(); },
        fetchDashboard: () => {
            fetch(API_URL + '?action=getAdminDashboard&pw=' + App.State.adminPw).then(r=>r.json()).then(res=>{
                if(res.status==='success') {
                    bootstrap.Modal.getInstance(document.getElementById('adminLoginModal')).hide();
                    App.Router.go('admin');

                    // 1. Translate Revenue & Store Status
                    document.getElementById('admin-revenue').innerText = App.Utils.fmt(parseFloat(res.revenue));
                    const isManualClosed = res.config.Manual_Close === true;
                    document.getElementById('admin-store-status').innerText = isManualClosed ? App.I18n.t('status_closed') : App.I18n.t('status_open');
                    document.getElementById('admin-store-status').className = isManualClosed ? "h3 fw-bold text-danger" : "h3 fw-bold text-success";

                    const list = document.getElementById('admin-orders-list');
                    if(res.orders.length === 0) list.innerHTML = `<p class="text-muted text-center">${App.I18n.t('admin_no_orders')}</p>`;
                    else {
                        list.innerHTML = res.orders.map(o => {
                            // 2. Translate Order Status (Pending, etc.)
                            const statusKey = 'status_' + o.status.toLowerCase().replace(/\s/g,'');
                            const translatedStatus = App.I18n.t(statusKey) || o.status;

                            return `
                            <div class="admin-card ${o.status==='Completed'?'completed':''}">
                                <div class="d-flex justify-content-between">
                                    <strong>#${o.id}</strong>
                                    <span class="badge bg-light text-dark border">${translatedStatus}</span>
                                </div>
                                <div>${o.name} - ${o.phone}</div>
                                <div class="small text-muted">${o.items}</div>
                                <div class="fw-bold mt-2 text-primary">${App.Utils.fmt(o.total)}</div>
                                <div class="mt-2 d-flex gap-2">
                                    <button class="btn btn-sm btn-warning" onclick="App.Admin.updateStatus('${o.id}', 'Preparing')">${App.I18n.t('btn_prep')}</button>
                                    <button class="btn btn-sm btn-info" onclick="App.Admin.updateStatus('${o.id}', 'On the Way')">${App.I18n.t('btn_ship')}</button>
                                    <button class="btn btn-sm btn-success" onclick="App.Admin.updateStatus('${o.id}', 'Completed')">${App.I18n.t('btn_complete')}</button>
                                    <button class="btn btn-sm btn-danger" onclick="App.Admin.updateStatus('${o.id}', 'Cancelled')">X</button>
                                    <button class="btn btn-sm btn-dark" onclick="App.Admin.printReceipt('${o.id}')"><i class="bi bi-printer"></i></button>
                                </div>
                            </div>`;
                        }).join('');
                    }

                    if(App.State.adminInterval) clearInterval(App.State.adminInterval);
                    App.State.adminInterval = setInterval(App.Admin.fetchDashboard, 30000); 
                } else alert(res.message);
            });
        },
        updateStatus: (id, st) => {
            fetch(API_URL, {method:'POST', body:JSON.stringify({action:'updateStatus', data:{password:App.State.adminPw, orderId:id, newStatus:st}})})
            .then(r=>r.json()).then(res=>{ if(res.status==='success') App.Admin.fetchDashboard(); });
        },
        toggleStore: () => {
             const current = document.getElementById('admin-store-status').innerText === "CLOSED";
             const newState = !current; 
             fetch(API_URL, {method:'POST', body:JSON.stringify({action:'toggleStore', data:{password:App.State.adminPw, state:newState}})})
             .then(r=>r.json()).then(res=>{ if(res.status==='success') App.Admin.fetchDashboard(); });
        },
        printReceipt: (oid) => {
            // Placeholder for thermal printer logic (Phase 10)
            alert("Printing Order #" + oid + "...");
        }
    },

    // 12. ROUTER
    Router: {
        go: (route) => {
            App.State.currentView = route; window.scrollTo(0,0); document.querySelectorAll('.module-section').forEach(e => e.classList.remove('active'));
            if(route === 'wishlist') { if(App.State.user) { const target = document.getElementById('profile-module'); target.classList.add('active'); setTimeout(() => { const btn = document.querySelector('button[data-bs-target="#tab-wish"]'); if(btn) btn.click(); }, 50); return; } else { alert("Please login to save items."); App.Auth.openModal(); return; } }
            if(route === 'settings') { const target = document.getElementById('settings-module'); target.classList.add('active'); return; }
            if(route === 'admin') { const target = document.getElementById('admin-module'); if(target) target.classList.add('active'); return; } 
            if(route === 'driver') { const target = document.getElementById('driver-module'); if(target) target.classList.add('active'); return; }
            const target = document.getElementById(route + '-module'); if(target) target.classList.add('active');
            if(route === 'cart') App.Cart.render(); if(route === 'profile') App.Auth.check();
            const bc = document.getElementById('breadcrumbs'); if(bc) { if (route === 'home') bc.innerHTML = `<span class="fw-bold"><i class="bi bi-house-door-fill"></i> ${App.I18n.t('nav_home')}</span>`; else bc.innerHTML = `<span class="crumb-link" onclick="App.Router.go('home')">${App.I18n.t('nav_home')}</span> <span class="mx-1">/</span> <b class="text-dark text-capitalize">${App.I18n.t('nav_'+route) || route}</b>`; }
        }
    },

    // 13. AUTH
    Auth: {
        openModal: () => new bootstrap.Modal(document.getElementById('authModal')).show(),
        login: () => { const p = App.Utils.el('login-phone').value; const pass = App.Utils.el('login-pass').value; if(!p) return alert('Enter Phone'); fetch(API_URL, {method:'POST', body:JSON.stringify({action:'login', data:{phone:p, password:pass}})}).then(r=>r.json()).then(res=>{ if(res.status==='success') { App.State.user = {id:res.userId, name:res.name, phone:p, authToken: res.authToken}; App.Utils.save('se_user', App.State.user); location.reload(); } else alert(res.message); }); },
        register: () => { 
            const n = App.Utils.el('reg-name').value; 
            const p = App.Utils.el('reg-phone').value; 
            const pass = App.Utils.el('reg-pass').value; 
            const ref = App.Utils.el('reg-ref').value; 
            if(!App.Utils.isValidPhone(p)) return alert("Invalid Phone Number. Use 06... or 07..."); 
            fetch(API_URL, {method:'POST', body:JSON.stringify({action:'register', data:{name:n, phone:p, password:pass, referralCode:ref}})})
            .then(r=>r.json()).then(res=>{ 
                if(res.status==='success') { 
                    App.State.user = {id:res.userId, name:n, phone:p, authToken: res.authToken}; 
                    App.Utils.save('se_user', App.State.user); 
                    location.reload(); 
                } else alert(res.message); 
            }); 
        },
        logout: () => { App.UI.confirm(App.I18n.t('logout_title'), App.I18n.t('logout_msg'), () => { localStorage.removeItem('se_user'); location.reload(); }); },
        check: () => { const u = App.State.user; if(u) { App.Utils.el('profile-logged-in').style.display = 'block'; App.Utils.el('profile-logged-out').style.display = 'none'; App.Utils.el('user-name-display').innerText = u.name; 
        const authBtn = App.Utils.el('auth-btn'); if(authBtn) authBtn.innerHTML = '<i class="bi bi-person-check-fill text-success fs-5"></i>'; 
        App.Profile.renderHistory(); if(App.Wishlist && typeof App.Wishlist.render === 'function') App.Wishlist.render(); App.Profile.renderAddresses(); App.Profile.updatePointsUI(); const addrSelect = document.getElementById('cart-addr-select'); if(addrSelect && (App.State.addresses.home || App.State.addresses.office)) { addrSelect.innerHTML = `<option value="">${App.I18n.t('select_addr_ph')}</option>`; if(App.State.addresses.home) addrSelect.innerHTML += `<option value="Home">${App.I18n.t('lbl_home')}: ${typeof App.State.addresses.home === 'string' ? App.State.addresses.home : App.State.addresses.home.full}</option>`; } if(App.State.addresses.office) addrSelect.innerHTML += `<option value="Office">${App.I18n.t('lbl_office')}: ${typeof App.State.addresses.office === 'string' ? App.State.addresses.office : App.State.addresses.office.full}</option>`; } }
    },

    // 14. PROFILE
    Profile: {
        openAddressModal: (addrType = null) => { const modalEl = document.getElementById('addressModal'); const modal = bootstrap.Modal.getOrCreateInstance(modalEl); if(addrType) { const data = App.State.addresses[addrType.toLowerCase()]; if(data && typeof data === 'object') { const getEl = (id) => document.getElementById(id); if(getEl('addr-name')) getEl('addr-name').value = data.name || ''; if(getEl('addr-street')) getEl('addr-street').value = data.street || ''; if(getEl('addr-apt')) getEl('addr-apt').value = data.apt || ''; if(getEl('addr-city')) getEl('addr-city').value = data.city || ''; if(getEl('addr-zip')) getEl('addr-zip').value = data.zip || ''; if(getEl('addr-country')) getEl('addr-country').value = data.country || ''; if(getEl('addr-type')) getEl('addr-type').value = addrType; } } modal.show(); },
        renderAddresses: () => { const c = document.getElementById('address-list-grid'); if(!c) return; const a = App.State.addresses; let html = ''; if(a.home) html += App.Profile.createAddrCard('Home', a.home); if(a.office) html += App.Profile.createAddrCard('Office', a.office); if(!html) html = `<div class="col-12 text-center text-muted py-3">${App.I18n.t('addr_empty')}</div>`; c.innerHTML = html; App.I18n.updateDOM(); },
        createAddrCard: (type, data) => { const display = (typeof data === 'string') ? data : (data.full || `${data.street} ${data.apt}<br>${data.city}, ${data.zip}`); const labelKey = type === 'Home' ? 'lbl_home' : 'lbl_office'; return `<div class="col-md-6"><div class="address-card"><span class="address-tag" data-i18n="${labelKey}">${App.I18n.t(labelKey)}</span><h6 class="fw-bold mb-3"><i class="bi bi-geo-alt-fill"></i> ${data.name || type}</h6><p class="small text-muted mb-3">${display}</p><button class="btn btn-sm btn-outline-dark rounded-pill px-3" onclick="App.Profile.openAddressModal('${type}')" data-i18n="btn_edit">Edit</button></div></div>`; },
        saveAddress: () => { if(!App.State.user) return alert("Please login first"); const btn = document.getElementById('save-addr-btn'); if(btn) { btn.disabled = true; btn.innerText = App.I18n.t('btn_saving'); } const getVal = (id) => { const el = document.getElementById(id); return el ? el.value : ""; }; const type = getVal('addr-type'); const addrData = { name: getVal('addr-name'), street: getVal('addr-street'), apt: getVal('addr-apt'), city: getVal('addr-city'), zip: getVal('addr-zip'), country: getVal('addr-country'), full: `${getVal('addr-street')} ${getVal('addr-apt')}, ${getVal('addr-city')}` }; if(!addrData.street) { if(btn) { btn.disabled = false; btn.innerText = App.I18n.t('btn_save_addr'); } return alert('Enter Street Address'); } fetch(API_URL, {method:'POST', body:JSON.stringify({ action: 'updateAddress', data: { userId: App.State.user.id, authToken: App.State.user.authToken, type: type, addressJson: JSON.stringify(addrData) } })}).then(r=>r.json()).then(res=>{ if(res.status==='success') { if(type==='Home') App.State.addresses.home = addrData; else App.State.addresses.office = addrData; App.Profile.renderAddresses(); bootstrap.Modal.getInstance(document.getElementById('addressModal')).hide(); App.UI.toast('Address Saved'); } else { alert("Save failed: " + res.message); } if(btn) { btn.disabled = false; btn.innerText = App.I18n.t('btn_save_addr'); } }).catch(e => { alert("Error saving"); if(btn) btn.disabled = false; }); },
        saveSettings: () => { if(!App.State.user) return; const btn = document.getElementById('save-settings-btn'); if(btn) { btn.disabled = true; btn.innerText = App.I18n.t('btn_saving'); } const n = document.getElementById('setting-name').value; const e = document.getElementById('setting-email').value; const p = document.getElementById('setting-phone').value; fetch(API_URL, {method:'POST', body:JSON.stringify({ action: 'updateUser', data: { userId: App.State.user.id, authToken: App.State.user.authToken, name: n, email: e, phone: p } })}).then(r=>r.json()).then(res=>{ if(res.status==='success') App.UI.toast(App.I18n.t('msg_settings_saved')); if(btn) { btn.disabled = false; btn.innerText = App.I18n.t('btn_save_changes'); } }); },
        renderHistory: () => { const list = document.getElementById('order-history-list'); if(!list) return; if(App.State.history.length === 0) { list.innerHTML = `<p class="text-muted small py-2">${App.I18n.t('history_empty')}</p>`; return; } list.innerHTML = ''; App.State.history.forEach(o => { const displayTotal = App.Utils.fmt(parseFloat(o.total)) || "0.00 DH"; let thumbsHtml = ''; try { const items = JSON.parse(o.items); if(items && items.length) { thumbsHtml = items.slice(0, 3).map(itemName => { var img = IMG_FALLBACK; for (var k = 0; k < App.State.catalog.length; k++) { var prod = App.State.catalog[k]; if ((typeof prod.title === 'object' && (itemName.includes(prod.title.en) || itemName.includes(prod.title.fr) || itemName.includes(prod.title.ar))) || (typeof prod.title === 'string' && itemName.includes(prod.title))) { img = prod.image; break; } } return `<img src="${App.Utils.optimizeImg(img)}" class="order-thumb-img"/>`; }).join(''); } } catch(e) {} const statusClass = (o.status === 'Completed' || o.status === 'Sent') ? 'status-pill-completed' : 'status-pill-processing'; list.innerHTML += `<div class="order-card-modern"><div class="d-flex justify-content-between mb-3"><span class="fw-bold text-dark">#${o.id}</span><span class="text-muted small">${new Date(o.date).toLocaleDateString()}</span></div><div class="order-thumbs d-flex gap-2 mb-3">${thumbsHtml}</div><div class="d-flex justify-content-between align-items-center mb-2"><span class="text-muted">${App.I18n.t('lbl_status')}</span><span class="${statusClass}">${App.I18n.t('status_' + o.status.toLowerCase()) || o.status}</span></div><div class="d-flex justify-content-between align-items-center mb-3"><span class="text-muted">${App.I18n.t('lbl_total')}</span><span class="fw-bold fs-5">${displayTotal}</span></div><div class="d-flex gap-2"><button class="btn btn-primary flex-grow-1 rounded-pill" onclick="App.Profile.showOrderDetail('${o.id}')">${App.I18n.t('btn_track')}</button><button class="btn btn-light flex-grow-1 rounded-pill" onclick="App.Profile.showOrderDetail('${o.id}')">${App.I18n.t('btn_details')}</button><button class="btn btn-outline-primary flex-grow-1 rounded-pill" onclick="App.Cart.reorder('${o.items.replace(/"/g, '"')}')"><i class="bi bi-arrow-repeat"></i> ${App.I18n.t('btn_reorder')}</button></div></div>`; }); },
        showOrderDetail: (id) => { 
            const o = App.State.history.find(x => x.id === id); if(!o) return; let itemsHtml = '<p class="text-muted">No item details.</p>'; try { const items = JSON.parse(o.items); if(items && items.length) { itemsHtml = `<div class="bg-light p-3 rounded mb-3">` + items.map(i => { let title = i; let qty =1; if(i.match(/^\d+x/)) { let parts = i.split('x '); qty = parseInt(parts[0]); title = parts.slice(1).join('x '); } let match = null; for (let k = 0; k < App.State.catalog.length; k++) { const p = App.State.catalog[k]; if (typeof p.title === 'object') { if ((p.title.en && title.includes(p.title.en)) || (p.title.fr && title.includes(p.title.fr)) || (p.title.ar && title.includes(p.title.ar))) { match = p; break; } } else if (typeof p.title === 'string' && title.includes(p.title)) { match = p; break; } } const img = match ? (match.image || IMG_FALLBACK) : IMG_FALLBACK; const unitPrice = match ? match.price_MAD : 0; const subtotal = unitPrice * qty; const displayPrice = unitPrice > 0 ? App.Utils.fmt(subtotal) : ''; 
            const reviewBtn = (o.status === 'Completed' && match) ? `<button class="btn btn-link btn-sm text-decoration-none p-0 ms-2" onclick="App.UI.openReviewModal('${match.id}')"><small>★ ${App.I18n.t('btn_write_review')}</small></button>` : '';
            return `<div class="order-detail-row"><img src="${App.Utils.optimizeImg(img)}" class="od-img"/><div><div class="fw-bold small">${title}</div><div class="text-primary small fw-bold">${displayPrice} ${reviewBtn}</div></div></div>`; }).join('') + `</div>`; } } catch(e) {} 
            let totalVal = parseFloat(o.total); if (isNaN(totalVal)) totalVal = 0; const displayTotalTotal = App.Utils.fmt(totalVal);

            const statuses = ['Pending', 'Preparing', 'On the Way', 'Delivered'];
            let currentStep = statuses.indexOf(o.status);
            if(o.status === 'Completed' || o.status === 'Sent') currentStep = 3;
            if(currentStep === -1) currentStep = 0;

            const timelineHtml = `<div class="timeline">` + statuses.map((s, idx) => {
                const isActive = idx <= currentStep ? 'active' : '';
                const timeLabel = idx === 0 ? new Date(o.date).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}) : '';
                return `<div class="timeline-item ${isActive}"><span class="small ${isActive ? 'fw-bold text-success' : 'text-muted'}">${App.I18n.t('status_' + s.toLowerCase().replace(/\s/g,''))}</span> <span class="small text-muted ms-2">${timeLabel}</span></div>`;
            }).join('') + `</div>`;

            const html = `<div class="p-3"><div class="d-flex justify-content-between align-items-center mb-3"><h5 class="m-0 fw-bold">#${o.id}</h5><span class="badge bg-primary">${App.I18n.t('status_' + o.status.toLowerCase()) || o.status}</span></div><h6 class="small fw-bold text-muted mb-2 text-uppercase" data-i18n="lbl_timeline">${App.I18n.t('lbl_timeline')}</h6>${timelineHtml}${itemsHtml}<div class="d-flex justify-content-between fw-bold border-top pt-3"><span>${App.I18n.t('total_caps')}</span><span class="text-primary">${displayTotalTotal}</span></div><button class="btn btn-outline-dark w-100 rounded-pill mt-4" data-bs-dismiss="modal" data-i18n="btn_close">Close</button></div>`; 
            document.getElementById('order-detail-body').innerHTML = html; new bootstrap.Modal(document.getElementById('orderDetailModal')).show(); App.I18n.updateDOM(); 
        },
        updatePointsUI: () => {
            const el = document.querySelector('.profile-info .sub-link');
            if(el && App.State.user) {
                el.innerHTML = `<span class="points-badge"><i class="bi bi-star-fill me-1"></i> ${App.State.user.points} ${App.I18n.t('lbl_pts')}</span>`;
            }
        }
    },

	// 19. DRIVER MODE
    Driver: {
        pin: "2024",
        interval: null,
        openLogin: () => {
            const modal = document.getElementById('driverLoginModal');
            if(modal) new bootstrap.Modal(modal).show();
            else alert("Driver Modal Missing");
        },
        login: () => {
            const input = document.getElementById('driver-pin').value;
            if(input !== App.Driver.pin) return alert("Wrong PIN");
            const el = document.getElementById('driverLoginModal');
            const modal = bootstrap.Modal.getInstance(el);
            if(modal) modal.hide();

            App.Driver.fetchOrders();
            App.Router.go('driver');

            if(App.Driver.interval) clearInterval(App.Driver.interval);
            App.Driver.interval = setInterval(App.Driver.fetchOrders, 15000);
        },
        fetchOrders: () => {
            if(!App.State.adminPw) App.State.adminPw = "admin123";
            fetch(API_URL + '?action=getAdminDashboard&pw=' + App.State.adminPw).then(r=>r.json()).then(res => {
                if(res.status !== 'success') return;
                const list = document.getElementById('driver-orders-list');
                if(!list) return;

                const activeOrders = res.orders.filter(o => o.status === 'Preparing' || o.status === 'On the Way');

                if(activeOrders.length === 0) {
                    list.innerHTML = `<div class="text-center text-muted mt-5"><h5>No active deliveries</h5><p>Wait for kitchen...</p></div>`;
                    return;
                }

                list.innerHTML = activeOrders.map(o => {
                    const mapLink = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(o.phone + " Morocco")}`;
                    const waLink = `https://wa.me/${o.phone}`;

                    // Translate Status
                    const statusKey = 'status_' + o.status.toLowerCase().replace(/\s/g,'');
                    const translatedStatus = (App.I18n && App.I18n.t(statusKey)) ? App.I18n.t(statusKey) : o.status;

                    return `
                    <div class="card border-0 shadow-sm mb-3">
                        <div class="card-body">
                            <div class="d-flex justify-content-between mb-2">
                                <span class="badge bg-warning text-dark">#${o.id}</span>
                                <span class="fw-bold">${translatedStatus}</span>
                            </div>
                            <h5 class="fw-bold mb-1">${o.name}</h5>
                            <p class="text-muted mb-3"><i class="bi bi-geo-alt-fill text-danger"></i> ${App.I18n.t('lbl_click_nav')}</p>
                            <div class="d-grid gap-2">
                                <a href="${mapLink}" target="_blank" class="btn btn-outline-primary fw-bold"><i class="bi bi-map"></i> ${App.I18n.t('btn_open_maps')}</a>
                                <a href="${waLink}" target="_blank" class="btn btn-outline-success fw-bold"><i class="bi bi-whatsapp"></i> ${App.I18n.t('btn_call_wa')}</a>
                                <button class="btn btn-dark fw-bold py-2 mt-2" onclick="App.Admin.updateStatus('${o.id}', 'Delivered')">✅ ${App.I18n.t('btn_mark_delivered')}</button>
                            </div>
                        </div>
                    </div>`;
                }).join('');
            });
        }
    },

    // 17. SOCIAL & ENGAGEMENT (Phase 9)
    Social: {
        init: () => {
            setTimeout(App.Social.showNotification, 10000);
            setInterval(App.Social.showNotification, 45000);
        },
        shareReferral: () => {
            if(!App.State.user) return App.Auth.openModal();
            const code = App.State.user.referralCode || App.State.user.id.substring(0,6).toUpperCase(); 
            const text = `${App.I18n.t('msg_share_ref')} *${code}* %0A ${window.location.href}`;
            window.open(`https://wa.me/?text=${text}`, '_blank');
        },
        showNotification: () => {
            const names = ['Ahmed', 'Sara', 'Karim', 'Salma', 'Omar', 'Yasmine', 'Fatima', 'Mehdi'];
            const cities = ['Casablanca', 'Rabat', 'Marrakech', 'Tangier', 'Agadir'];
            const items = App.State.catalog.length > 0 ? App.State.catalog : [{title: {en: "Sushi Set"}, image: ""}];

            const rName = names[Math.floor(Math.random() * names.length)];
            const rCity = cities[Math.floor(Math.random() * cities.length)];
            const rItem = items[Math.floor(Math.random() * items.length)];
            const rTitle = App.Utils.getLocalizedText(rItem.title);
            const rImg = rItem.image || "https://placehold.co/100";

            const msg = `<b>${rName}</b> (${rCity}) ${App.I18n.t('txt_social_proof')} <br/> <span class="text-primary">${rTitle}</span>`;

            const toast = document.createElement('div');
            toast.className = 'custom-toast border-success social-proof-toast';
            toast.innerHTML = `<div class="d-flex align-items-center gap-3"><img src="${rImg}" style="width:40px;height:40px;border-radius:50%;object-fit:cover; border:1px solid #ddd;"><div><small class="d-block text-success fw-bold text-uppercase" style="font-size:0.65rem"><i class="bi bi-patch-check-fill"></i> ${App.I18n.t('lbl_verified')}</small><span style="font-size:0.8rem; line-height:1.2; display:block;">${msg}</span></div></div>`;

            const container = document.getElementById('toast-container');
            if(container) {
                container.appendChild(toast);
                setTimeout(() => { toast.style.opacity = '0'; setTimeout(()=>toast.remove(), 300); }, 5000);
            }
        }
    },
    // 20. PWA
    PWA: {
        deferredPrompt: null,
        init: () => {
            // 1. Generate Manifest
            const manifest = {
                "name": "SushiElite",
                "short_name": "SushiElite",
                "start_url": window.location.href,
                "display": "standalone",
                "background_color": "#ffffff",
                "theme_color": "#ce1212",
                "icons": [
                    { "src": "https://cdn-icons-png.flaticon.com/512/2252/2252076.png", "sizes": "192x192", "type": "image/png" },
                    { "src": "https://cdn-icons-png.flaticon.com/512/2252/2252076.png", "sizes": "512x512", "type": "image/png" }
                ]
            };
            const link = document.createElement('link');
            link.rel = 'manifest';
            link.href = 'data:application/manifest+json;base64,' + btoa(JSON.stringify(manifest));
            document.head.appendChild(link);

            // 2. Listen for Install Event
            window.addEventListener('beforeinstallprompt', (e) => {
                e.preventDefault();
                App.PWA.deferredPrompt = e;
                // Show the Beautiful Popup after 2 seconds
                setTimeout(() => {
                    document.getElementById('install-prompt').classList.add('active');
                }, 2000);
            });

            // 3. Handle App Installed
            window.addEventListener('appinstalled', () => {
                App.PWA.deferredPrompt = null;
                document.getElementById('install-prompt').classList.remove('active');
                App.UI.toast("App Installed Successfully!", "success");
            });
        },
        install: async () => {
            const promptEvent = App.PWA.deferredPrompt;
            if (!promptEvent) return;
            promptEvent.prompt();
            const { outcome } = await promptEvent.userChoice;
            if (outcome === 'accepted') {
                console.log('User accepted');
            }
            App.PWA.deferredPrompt = null;
            document.getElementById('install-prompt').classList.remove('active');
        }
    },
    // 21. SEO
    SEO: {
        init: () => {
            const script = document.getElementById('json-ld-store');
            const data = {
                "@context": "https://schema.org",
                "@type": "Restaurant",
                "name": "SushiElite",
                "image": "https://cdn-icons-png.flaticon.com/512/2252/2252076.png",
                "telephone": App.Config.waNumber,
                "priceRange": "$$",
                "address": {
                    "@type": "PostalAddress",
                    "addressCountry": "MA"
                }
            };
            script.textContent = JSON.stringify(data);
        },
        setProduct: (p) => {
            const script = document.getElementById('json-ld-store');
            const data = {
                "@context": "https://schema.org",
                "@type": "Product",
                "name": App.Utils.getLocalizedText(p.title),
                "image": p.image || IMG_FALLBACK,
                "description": App.Utils.getLocalizedText(p.desc).replace(/<[^>]*>?/gm, ''),
                "offers": {
                    "@type": "Offer",
                    "priceCurrency": "MAD",
                    "price": p.price_MAD,
                    "availability": p.stock > 0 ? "https://schema.org/InStock" : "https://schema.org/OutOfStock"
                }
            };
            script.textContent = JSON.stringify(data);
        }
    }
};

document.addEventListener('DOMContentLoaded', () => {
    if (typeof AOS !== 'undefined') { AOS.init(); }

    // 1. Core Logic Init
    App.Catalog.searchDebounced = App.Utils.debounce(App.Catalog._searchImpl, 300);
    App.State.cart = App.Utils.load('se_cart') || [];
    App.State.wishlist = App.Utils.load('se_wish') || [];
    App.State.recent = App.Utils.load('se_recent') || [];
    App.State.user = App.Utils.load('se_user');

    // 2. Offline Listeners
    window.addEventListener('offline', () => { App.UI.toast("You are offline. Changes saved locally.", "warning"); });
    window.addEventListener('online', () => { App.UI.toast("Back online!", "success"); App.API.init(); });

    // 3. Welcome / Init Logic
    if (!localStorage.getItem('se_setup_done')) {
        const browserLang = navigator.language.slice(0,2);
        if (['en', 'fr', 'ar'].includes(browserLang)) {
            App.State.tempLang = browserLang;
            setTimeout(() => {
                 ['en','fr','ar'].forEach(l => document.getElementById('wel-lang-'+l)?.classList.remove('selected'));
                 document.getElementById('wel-lang-'+browserLang)?.classList.add('selected');
                 const btn = document.getElementById('btn-welcome-start');
                 if(btn && App.State.translations['btn_start_ordering']) btn.innerText = App.State.translations['btn_start_ordering'][browserLang];
            }, 500);
        }
        const welcomeModal = new bootstrap.Modal(document.getElementById('welcomeModal'));
        welcomeModal.show();
    } else {
        App.State.lang = localStorage.getItem('se_lang') || 'en';
        const storedCurr = localStorage.getItem('se_curr');
        if(storedCurr) { App.State.currency = storedCurr; }
        if(App.State.wishlist) App.Utils.el('nav-wish-count').innerText = App.State.wishlist.length;
        const storedTheme = localStorage.getItem('se_theme');
        if(storedTheme) { document.body.setAttribute('data-theme', storedTheme); if(document.getElementById('theme-toggle')) document.getElementById('theme-toggle').checked = (storedTheme === 'dark'); }
        document.documentElement.setAttribute('dir', App.State.lang === 'ar' ? 'rtl' : 'ltr');
        App.UI.updateIcons();
    }

    App.Router.go('home');
    App.API.init();
    App.Auth.check();
    App.Cart.render();

	App.UI.hideLoader();

    // Init SEO & PWA & Social
    if(App.PWA) App.PWA.init();
    if(App.SEO) App.SEO.init();
    if(App.Social) App.Social.init();

    // Phase 12: Abandoned Cart Check
    if (App.State.cart.length > 0) {
        const lastSaved = localStorage.getItem('se_last_save');
        const now = Date.now();
        // If cart exists and last save was > 1 hour ago (3600000 ms)
        if (lastSaved && (now - parseInt(lastSaved)) > 3600000) {
            const toast = document.createElement('div');
            toast.className = 'custom-toast border-primary';
            toast.innerHTML = `
                <div>
                    <strong class="d-block mb-1">SushiElite</strong>
                    <span class="small">${App.I18n.t('msg_welcome_back')}</span>
                </div>
                <button class="btn btn-sm btn-primary rounded-pill ms-3" onclick="App.Router.go('cart'); this.parentElement.remove()">${App.I18n.t('btn_resume_order')}</button>
            `;
            document.getElementById('toast-container').appendChild(toast);
        }
    }
    // Update save time whenever cart changes
    const originalSave = App.Utils.save;
    App.Utils.save = function(key, val) {
        if(key === 'se_cart') localStorage.setItem('se_last_save', Date.now());
        originalSave(key, val);
    };

    // 4. SAFE SCRIPT LOADER (Fixes Calendar & Confetti)
    const loadScript = (src, callback) => {
        const s = document.createElement('script');
        s.src = src;
        s.onload = callback;
        document.head.appendChild(s);
    };

    // Load Confetti
    loadScript('https://cdn.jsdelivr.net/npm/canvas-confetti@1.6.0/dist/confetti.browser.min.js', null);

    // Load Flatpickr Chain
    loadScript('https://cdn.jsdelivr.net/npm/flatpickr', () => {
        loadScript('https://npmcdn.com/flatpickr/dist/l10n/ar.js', () => {
            loadScript('https://npmcdn.com/flatpickr/dist/l10n/fr.js', () => {

                // Initialize Calendar
                const currentLang = App.State.lang;
                const localeMap = { 'ar': 'ar', 'fr': 'fr', 'en': 'default' };

                flatpickr("#res-date", { 
                    minDate: "today", 
                    dateFormat: "Y-m-d",
                    locale: localeMap[currentLang] || 'default',
                    disableMobile: false, 
                    allowInput: false,    
                    onOpen: function(selectedDates, dateStr, instance) {
                        document.activeElement.blur();
                    }
                });

            });
        });
    });
});
//
